glsl:
vec4 effect(vec2 uv) {
  vec4 c = getColor(uv);
  float l = luma(c.rgb) * 1.6;
  vec3 g = vec3(0.1, 1.0, 0.25) * l;
  g += (hash(uv * 700.0 + floor(uTime * 24.0)) - 0.5) * 0.2;
  g *= 0.85 + 0.15 * sin(uv.y / uTexel.y * 1.5);
  vec2 d = (uv - 0.5) * vec2(uRatio, 1.0);
  g *= smoothstep(0.75, 0.45, length(d));
  return vec4(mix(c.rgb, g, uAmount), getColor(uv).a);
}
